package com.mailservice.core

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.io.File
import java.security.MessageDigest

data class EmailRequest(
    val to: String,
    val subject: String,
    val body: String,
    val templateId: String? = null,
    val templateVars: Map<String, String> = emptyMap()
)

data class RateLimitEntry(val count: AtomicInteger, val windowStart: Instant)

class TemplateEngine(private val templateDir: String = "/opt/mail/templates") {

    private val directivePattern = Regex("""\$\{([a-zA-Z_][a-zA-Z0-9_.]*)}""")
    private val includePattern = Regex("""<!--#include\s+(virtual|file)="([^"]+)"\s*-->""")

    fun resolveTemplate(templateId: String, vars: Map<String, String>): String {
        val templatePath = sanitizeTemplatePath(templateId)
        val templateFile = File(templateDir, templatePath)
        if (!templateFile.exists()) throw IllegalArgumentException("Template not found: $templateId")
        var content = templateFile.readText()
        content = substituteVariables(content, vars)
        content = processIncludes(content, vars)
        return content
    }

    private fun sanitizeTemplatePath(templateId: String): String {
        val normalized = templateId.replace("..", "").replace("//", "/")
        if (!normalized.endsWith(".html") && !normalized.endsWith(".txt")) {
            return "$normalized.html"
        }
        return normalized
    }

    private fun substituteVariables(content: String, vars: Map<String, String>): String {
        return directivePattern.replace(content) { match ->
            val varName = match.groupValues[1]
            vars[varName] ?: ""
        }
    }

    fun processIncludes(content: String, vars: Map<String, String>): String {
        return includePattern.replace(content) { match ->
            val includeType = match.groupValues[1]
            val includePath = match.groupValues[2]
            resolveInclude(includeType, includePath, vars)
        }
    }

    private fun resolveInclude(type: String, path: String, vars: Map<String, String>): String {
        val resolvedPath = when (type) {
            "virtual" -> path
            "file" -> "$templateDir/$path"
            else -> return ""
        }
        val file = File(resolvedPath)
        return if (file.exists() && file.canRead()) {
            val included = file.readText()
            substituteVariables(included, vars)
        } else ""
    }
}

class RateLimiter(private val maxPerWindow: Int = 100, private val windowSeconds: Long = 3600) {
    private val limits = ConcurrentHashMap<String, RateLimitEntry>()

    fun checkLimit(senderKey: String): Boolean {
        val now = Instant.now()
        val entry = limits.compute(senderKey) { _, existing ->
            if (existing == null || existing.windowStart.plusSeconds(windowSeconds).isBefore(now)) {
                RateLimitEntry(AtomicInteger(1), now)
            } else {
                existing.count.incrementAndGet()
                existing
            }
        }
        return (entry?.count?.get() ?: 0) <= maxPerWindow
    }
}

class EmailSender(
    private val smtpHost: String = "localhost",
    private val smtpPort: Int = 587,
    private val maxRetries: Int = 3
) {
    private val templateEngine = TemplateEngine()
    private val rateLimiter = RateLimiter()

    fun sendEmail(request: EmailRequest, senderIdentity: String): Result<String> {
        val senderKey = computeSenderKey(senderIdentity)
        if (!rateLimiter.checkLimit(senderKey)) {
            return Result.failure(RuntimeException("Rate limit exceeded for sender"))
        }

        val finalBody = if (request.templateId != null) {
            templateEngine.resolveTemplate(request.templateId, request.templateVars)
        } else {
            prepareRawBody(request.body, request.templateVars)
        }

        return retryWithBackoff(maxRetries) {
            deliverMessage(request.to, request.subject, finalBody)
        }
    }

    private fun prepareRawBody(body: String, vars: Map<String, String>): String {
        val engine = TemplateEngine()
        var processed = body
        // Process any embedded includes in raw body for rich email composition
        processed = engine.processIncludes(processed, vars)
        return processed
    }

    private fun computeSenderKey(identity: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(identity.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    private fun <T> retryWithBackoff(maxAttempts: Int, action: () -> T): Result<T> {
        var lastException: Exception? = null
        for (attempt in 1..maxAttempts) {
            try {
                return Result.success(action())
            } catch (e: Exception) {
                lastException = e
                if (attempt < maxAttempts) {
                    Thread.sleep((attempt * 1000L) + (Math.random() * 500).toLong())
                }
            }
        }
        return Result.failure(lastException ?: RuntimeException("Unknown error"))
    }

    private fun deliverMessage(to: String, subject: String, body: String): String {
        // Simulated SMTP delivery
        println("Delivering to $to: $subject")
        return "msg-${System.currentTimeMillis()}"
    }
}

